// 32-bit Kogge-Stone-style prefix adder.  The five prefix stages replace the
// long bit-by-bit carry propagation inferred from a plain 32-bit '+' operator.
module NPC_prefix_adder32(A, B, SUM);
    input  [31:0] A;
    input  [31:0] B;
    output [31:0] SUM;

    wire [31:0] p0;
    wire [31:0] g0;
    wire [31:0] p1, g1;
    wire [31:0] p2, g2;
    wire [31:0] p3, g3;
    wire [31:0] p4, g4;
    wire [31:0] p5, g5;
    wire [31:0] carry;

    assign p0 = A ^ B;
    assign g0 = A & B;

    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : GEN_PREFIX
            if (i < 1) begin
                assign p1[i] = p0[i];
                assign g1[i] = g0[i];
            end else begin
                assign p1[i] = p0[i] & p0[i-1];
                assign g1[i] = g0[i] | (p0[i] & g0[i-1]);
            end

            if (i < 2) begin
                assign p2[i] = p1[i];
                assign g2[i] = g1[i];
            end else begin
                assign p2[i] = p1[i] & p1[i-2];
                assign g2[i] = g1[i] | (p1[i] & g1[i-2]);
            end

            if (i < 4) begin
                assign p3[i] = p2[i];
                assign g3[i] = g2[i];
            end else begin
                assign p3[i] = p2[i] & p2[i-4];
                assign g3[i] = g2[i] | (p2[i] & g2[i-4]);
            end

            if (i < 8) begin
                assign p4[i] = p3[i];
                assign g4[i] = g3[i];
            end else begin
                assign p4[i] = p3[i] & p3[i-8];
                assign g4[i] = g3[i] | (p3[i] & g3[i-8]);
            end

            if (i < 16) begin
                assign p5[i] = p4[i];
                assign g5[i] = g4[i];
            end else begin
                assign p5[i] = p4[i] & p4[i-16];
                assign g5[i] = g4[i] | (p4[i] & g4[i-16]);
            end
        end

        for (i = 0; i < 32; i = i + 1) begin : GEN_SUM
            if (i == 0) begin
                assign carry[i] = 1'b0;
            end else begin
                assign carry[i] = g5[i-1];
            end
            assign SUM[i] = p0[i] ^ carry[i];
        end
    endgenerate
